const rtdal000020Source0001 = `as.matching <- function(x, ...) UseMethod("as.matching")`

const rtdal000020Source0002 = "as.matching.phylo <- function(x, labels = TRUE, ...)\n{\n    nb.tip <- length(x$tip.label)\n    nb.node <- x$Nnode\n    if (nb.tip != nb.node + 1)\n        stop(\"the tree must be dichotomous AND rooted.\")\n    x <- reorder(x, \"pruningwise\") # cannot use \"postorder\" here!\n    mat <- matrix(x$edge[, 2], ncol = 2, byrow = TRUE)\n    nodes <- x$edge[seq(by = 2, length.out = nb.node), 1]\n    ## we can use match() becoz each node appears once in `mat'\n    O <- match(mat, nodes)\n    new.nodes <- 1:nb.node + nb.tip\n    sel <- !is.na(O)\n    mat[sel] <- new.nodes[O[sel]]\n    mat <- t(apply(mat, 1, sort))\n\n    obj <- list(matching = mat)\n    if (!is.null(x$edge.length))\n        warning(\"branch lengths have been ignored\")\n    if (labels) {\n        obj$tip.label <- x$tip.label\n        if (!is.null(x$node.label))\n            obj$node.label <- x$node.label[match(new.nodes, nodes)]\n    }\n    class(obj) <- \"matching\"\n    obj\n}"

const rtdal000020Source0003 = `as.phylo.matching <- function(x, ...)
{
    nb.node <- dim(x$matching)[1]
    nb.tip <- nb.node + 1
    N <- 2 * nb.node
    edge <- matrix(NA, N, 2)
    new.nodes <- numeric(N + 1)
    new.nodes[N + 1] <- nb.tip + 1
    nextnode <- nb.tip + 2
    j <- 1
    for (i in nb.node:1) {
        edge[j:(j + 1), 1] <- new.nodes[i + nb.tip]
        for (k in 1:2) {
            if (x$matching[i, k] > nb.tip) {
                edge[j + k - 1, 2] <- new.nodes[x$matching[i, k]] <- nextnode
                nextnode <- nextnode + 1
            } else edge[j + k - 1, 2] <- x$matching[i, k]
        }
        j <- j + 2
    }
    obj <- list(edge = edge)
    if (!is.null(x$tip.label)) obj$tip.label <- x$tip.label
    else obj$tip.label <- as.character(1:nb.tip)
    obj$Nnode <- nb.node
    class(obj) <- "phylo"
    read.tree(text = write.tree(obj))
}`

