const rtdal000094Source0001 = "pic <- function(x, phy, scaled = TRUE, var.contrasts = FALSE, rescaled.tree = FALSE)\n{\n    if (!inherits(phy, \"phylo\")) stop(\"object 'phy' is not of class \\\"phylo\\\"\")\n    if (is.null(phy$edge.length)) stop(\"your tree has no branch lengths\")\n    nb.tip <- length(phy$tip.label)\n    nb.node <- phy$Nnode\n    if (nb.node != nb.tip - 1)\n        stop(\"'phy' is not rooted and fully dichotomous\")\n    if (length(x) != nb.tip)\n        stop(\"length of phenotypic and of phylogenetic data do not match\")\n    if (any(is.na(x)))\n        stop(\"missing data in 'x': you may consider removing the species with missing data from your tree with the function 'drop.tip'.\")\n\n    phy <- reorder(phy, \"postorder\")\n    phenotype <- numeric(nb.tip + nb.node)\n\n    if (is.null(names(x))) {\n        phenotype[1:nb.tip] <- x\n    } else {\n        if (all(names(x) %in% phy$tip.label))\n          phenotype[1:nb.tip] <- x[phy$tip.label]\n        else {\n            phenotype[1:nb.tip] <- x\n            warning(\"the names of argument 'x' and the tip labels of the tree did not match: the former were ignored in the analysis.\")\n        }\n    }\n\n    ## No need to copy the branch lengths: they are rescaled\n    ## in the C code, so it's important to leave the default\n    ## `DUP = TRUE' of .C.\n    ans <- .C(C_pic, as.integer(nb.tip),\n              as.integer(phy$edge[, 1]), as.integer(phy$edge[, 2]),\n              as.double(phy$edge.length), as.double(phenotype),\n              double(nb.node), double(nb.node),\n              as.integer(var.contrasts), as.integer(scaled))\n\n    contr <- ans[[6]]\n    lbls <-\n        if (is.null(phy$node.label)) as.character(1:nb.node + nb.tip)\n        else phy$node.label\n    if (var.contrasts) {\n        contr <- cbind(contr, ans[[7]])\n        dimnames(contr) <- list(lbls, c(\"contrasts\", \"variance\"))\n    } else names(contr) <- lbls\n    if (rescaled.tree) {\n        phy$edge.length <- ans[[4]]\n        contr <- list(contr = contr, rescaled.tree = phy)\n    }\n    contr\n}"

const rtdal000094Source0002 = `pic.ortho <- function(x, phy, var.contrasts = FALSE, intra = FALSE)
{
    n <- length(x)
    m <- n - 1L # number of nodes
    phy <- reorder(phy, "postorder")
    xx <- unlist(lapply(x, mean)) # 'x' in Felsenstein's paper
    xx <- c(xx, numeric(m))
    delta.v <- numeric(n + m)
    s <- 1/lengths(x)
    s <- c(s, numeric(m))
    contrast <- var.cont <- numeric(m)

    i <- 1L
    while (i < m + n) {
        d1 <- phy$edge[i, 2]
        d2 <- phy$edge[i + 1L, 2]
        a <- phy$edge[i, 1]
        tmp1 <- 1/(phy$edge.length[i] + delta.v[d1])
        tmp2 <- 1/(phy$edge.length[i + 1L] + delta.v[d2])
        xx[a] <- (tmp1 * xx[d1] + tmp2 * xx[d2])/(tmp1 + tmp2)
        delta.v[a] <- 1/(tmp1 + tmp2)
        f1 <- tmp1/(tmp1 + tmp2)
        f2 <- tmp2/(tmp1 + tmp2)
        s[a] <- f1*f1 * s[d1] + f2*f2 * s[d2]
        tmp <- 1/(s[d1] + s[d2])
        contrast[a - n] <- (xx[d1] - xx[d2]) * sqrt(tmp)
        var.cont[a - n] <- (1/tmp1 + 1/tmp2) * tmp
        i <- i + 2L
    }

    lbls <-
        if (is.null(phy$node.label)) as.character(1:m + n)
        else phy$node.label

    if (var.contrasts) {
        contrast <- cbind(contrast, var.cont)
        dimnames(contrast) <- list(lbls, c("contrasts", "variance"))
    } else names(contrast) <- lbls

    if (intra) {
        intraspe.ctr <- function(x) {
            k <- length(x) - 1L
            if (!k) return(NULL)
            ctr <- numeric(k)
            ctr[1L] <- x[1L] - x[2L]
            if (k > 1)
                for (i in 2:k)
                    ctr[i] <- x[i + 1L] - mean(x[1:i])
            sqrt((1:k)/(1:k + 1)) * ctr
        }
        tmp <- lapply(x, intraspe.ctr)
        names(tmp) <- phy$tip.label
        attr(contrast, "intra") <- tmp
    }

    contrast
}`

const rtdal000094Source0003 = `varCompPhylip <- function(x, phy, exec = NULL)
{
    n <- Ntip(phy)
    if (is.vector(x)) x <- as.list(x)
    if (is.matrix(x) || is.data.frame(x)) {
        tmpx <- vector("list", n)
        for (i in 1:n) tmpx[[i]] <- x[i, , drop = FALSE]
        names(tmpx) <- rownames(x)
        x <- tmpx
    }
    p <- if (is.vector(x[[1]])) 1L else ncol(x[[1]])
    if (!is.null(names(x))) x <- x[phy$tip.label]

    phy <- makeLabel(phy, len = 10)
    lbs <- phy$tip.label

    ni <- sapply(x, function(xx) if (is.vector(xx)) 1L else nrow(xx))

    pfx <- tempdir()
    write.tree(phy, file = paste(pfx, "intree", sep = "/"))
    infile <- paste(pfx, "infile", sep = "/")
    file.create(infile)
    cat(n, " ", p, "\n", sep = "", file = infile, append = TRUE)
    for (i in 1:n) {
        cat(lbs[i], file = infile, append = TRUE)
        ## can surely be better but OK for the moment:
        cat(paste(rep(" ", 11 - nchar(lbs[i])), collapse = ""),
            file = infile, append = TRUE)
        cat(ni[i], "\n", sep = "", file = infile, append = TRUE)
        if (ni[i] == 1) {
            cat(x[[i]], sep = " ", file = infile, append = TRUE)
            cat("\n", file = infile, append = TRUE)
        } else write(t(x[[i]]), file = infile, ncolumns = p, append = TRUE)
    }

    if (is.null(exec))
        exec <-
            if (.Platform$OS.type == "unix") "phylip contrast"
            else "contrast"

    odir <- setwd(pfx)
    on.exit(setwd(odir))
    if (file.exists("outfile")) unlink("outfile")
    system(exec, intern = TRUE, input = c("W", "A", "Y"))
    varA <- scan("outfile", skip = 7, nlines = p, quiet = TRUE)
    varE <- scan("outfile", skip = 11 + p, nlines = p, quiet = TRUE)
    if (p > 1) {
        varA <- matrix(varA, p, p, byrow = TRUE)
        varE <- matrix(varE, p, p, byrow = TRUE)
    }
    list(varA = varA, varE = varE)
}`

