const rtdal000113Source0001 = "rTraitDisc <-\n    function(phy, model = \"ER\", k = if (is.matrix(model)) ncol(model) else 2,\n             rate = 0.1, states = LETTERS[1:k], freq = rep(1/k, k),\n             ancestor = FALSE, root.value = 1, ...)\n{\n    if (is.null(phy$edge.length))\n        stop(\"tree has no branch length\")\n    if (any(phy$edge.length < 0))\n        stop(\"at least one branch length negative\")\n\n    if (is.character(model)) {\n        switch(toupper(model), \"ER\" = {\n                   if (length(rate) != 1)\n                       stop(\"`rate' must have one element\")\n                   Q <- matrix(rate, k, k)\n               }, \"ARD\" = {\n                   if (length(rate) != k*(k - 1))\n                       stop(\"`rate' must have k(k - 1) elements\")\n                   Q <- matrix(0, k, k)\n                   Q[col(Q) != row(Q)] <- rate\n               }, \"SYM\" = {\n                   if (length(rate) != k*(k - 1)/2)\n                       stop(\"`rate' must have k(k - 1)/2 elements\")\n                   Q <- matrix(0, k, k)\n                   sel <- col(Q) < row(Q)\n                   Q[sel] <- rate\n                   Q <- t(Q)\n                   Q[sel] <- rate\n               })\n    }\n    if (is.matrix(model)) {\n        Q <- model\n        if (ncol(Q) != nrow(Q))\n            stop(\"the matrix given as `model' must be square\")\n    }\n\n    phy <- reorder(phy, \"postorder\")\n    n <- length(phy$tip.label)\n    N <- dim(phy$edge)[1]\n    ROOT <- n + 1L\n    x <- integer(n + phy$Nnode)\n    x[ROOT] <- as.integer(root.value)\n\n    anc <- phy$edge[, 1]\n    des <- phy$edge[, 2]\n    el <- phy$edge.length\n\n    if (!is.function(model)) {\n        if (requireNamespace(\"expm\", quietly = TRUE)) {\n            FOO <- expm::expm\n        } else {\n            warning(\"package expm not available, using ape::matexpo instead\")\n            FOO <- matexpo\n        }\n    }\n\n    if (is.function(model)) {\n        environment(model) <- environment() # to find 'k'\n        for (i in N:1) x[des[i]] <- model(x[anc[i]], el[i], ...)\n    } else {\n        freq <- rep(freq, each = k)\n        Q <- Q * freq\n        diag(Q) <- 0\n        diag(Q) <- -rowSums(Q)\n        for (i in N:1) {\n            p <- FOO(Q * el[i])[x[anc[i]], ]\n            x[des[i]] <- sample.int(k, size = 1, FALSE, prob = p)\n        }\n    }\n\n    if (ancestor) {\n        if (is.null(phy$node.label)) phy <- makeNodeLabel(phy)\n        names(x) <- c(phy$tip.label, phy$node.label)\n    } else {\n        x <- x[1:n]\n        names(x) <- phy$tip.label\n    }\n    class(x) <- \"factor\"\n    levels(x) <- states\n    x\n}"

const rtdal000113Source0002 = `rTraitCont <-
    function(phy, model = "BM", sigma = 0.1, alpha = 1, theta = 0,
             ancestor = FALSE, root.value = 0, ...)
{
    if (is.null(phy$edge.length))
        stop("tree has no branch length")
    if (any(phy$edge.length < 0))
        stop("at least one branch length negative")

    phy <- reorder(phy, "postorder")
    n <- length(phy$tip.label)
    N <- dim(phy$edge)[1]
    ROOT <- n + 1L
    x <- numeric(n + phy$Nnode)
    x[ROOT] <- root.value

    anc <- phy$edge[, 1]
    des <- phy$edge[, 2]
    el <- phy$edge.length

    if (is.function(model)) {
        environment(model) <- environment()
        for (i in N:1) x[des[i]] <- model(x[anc[i]], el[i], ...)
    } else {
        model <- pmatch(toupper(model), c("BM", "OU"))
        if (length(sigma) == 1) sigma <- rep(sigma, N)
        else if (length(sigma) != N)
            stop("'sigma' must have one or Nedge(phy) elements")
        if (model == 2) { # "OU"
            if (length(alpha) == 1) alpha <- rep(alpha, N)
            else if (length(alpha) != N)
                stop("'alpha' must have one or Nedge(phy) elements")
            if (length(theta) == 1) theta <- rep(theta, N)
            else if (length(theta) != N)
                stop("'theta' must have one or Nedge(phy) elements")
        }
        x <- .C(C_rTraitCont, as.integer(model), as.integer(N),
                as.integer(anc - 1L), as.integer(des - 1L), el,
                as.double(sigma), as.double(alpha), as.double(theta),
                x = x, NAOK = TRUE)$x
    }

    if (ancestor) {
        if (is.null(phy$node.label)) phy <- makeNodeLabel(phy)
        names(x) <- c(phy$tip.label, phy$node.label)
    } else {
        x <- x[1:n]
        names(x) <- phy$tip.label
    }
    x
}`

const rtdal000113Source0003 = `rTraitMult <-
    function(phy, model, p = 1, root.value = rep(0, p), ancestor = FALSE,
             asFactor = NULL, trait.labels = paste("x", 1:p, sep = ""), ...)
{
    phy <- reorder(phy, "postorder")
    n <- length(phy$tip.label)
    m <- phy$Nnode
    N <- dim(phy$edge)[1]
    ROOT <- n + 1L

    x <- matrix(0, n + m, p)
    x[ROOT, ] <- root.value

    anc <- phy$edge[, 1]
    des <- phy$edge[, 2]

    el <- phy$edge.length
    if (is.null(el)) el <- numeric(N)

    environment(model) <- environment() # to find 'p'

    for (i in N:1) x[des[i], ] <- model(x[anc[i], ], el[i], ...)

    if (ancestor) {
        if (is.null(phy$node.label)) phy <- makeNodeLabel(phy)
        rownames(x) <- c(phy$tip.label, phy$node.label)
    } else {
        x <- x[1:n, , drop = FALSE]
        rownames(x) <- phy$tip.label
    }
    x <- as.data.frame(x)
    names(x) <- trait.labels
    if (!is.null(asFactor)) {
        for (i in asFactor) {
            y <- x[, i]
            x[, i] <- factor(y, labels = LETTERS[1:length(unique(y))])
        }
    }
    x
}`

