const rtdal000124Source0016 = `str.multiPhylo <- function(object, ...)
{
    class(object) <- NULL
    cat('Class "multiPhylo"\n')
    str(object, ...)
}`

const rtdal000124Source0018 = `c.phylo <- function(..., recursive = TRUE)
{
    obj <- list(...)
    classes <- lapply(obj, class)
    isphylo <- sapply(classes, function(x) "phylo" %in% x)
    if (all(isphylo)) {
        class(obj) <- "multiPhylo"
        return(obj)
    }
    if (!recursive) return(obj)
    ismulti <- sapply(classes, function(x) "multiPhylo" %in% x)
    if (all(isphylo | ismulti)) {
        for (i in which(isphylo)) obj[[i]] <- .c_phylo_single(obj[[i]])
        ## added by Klaus:
        for (i in which(ismulti)) obj[[i]] <- .uncompressTipLabel(obj[[i]])
        obj <- .makeMultiPhyloFromObj(obj)
    } else {
        warning('some objects not of class "phylo" or "multiPhylo": argument recursive=TRUE ignored')
    }
    obj
}`

const rtdal000124Source0019 = `.makeMultiPhyloFromObj <- function(obj)
{
    n <- length(obj)
    N <- lengths(obj, FALSE)
    x <- vector("list", sum(N))
    a <- b <- 0L
    for (i in 1:n) {
        a <- b + 1L
        b <- b + N[i]
        z <- obj[[i]]
        x[a:b] <- z
        if (inherits(z, "multiPhylo") && !is.null(nms <- names(z)))
            names(x)[a:b] <- nms # see issue #37 on GH
    }
    class(x) <- "multiPhylo"
    x
}`

const rtdal000124Source0020 = `c.multiPhylo <- function(..., recursive = TRUE)
{
    obj <- list(...)
    if (!recursive) return(obj)
    classes <- lapply(obj, class)
    isphylo <- sapply(classes, function(x) "phylo" %in% x)
    ismulti <- sapply(classes, function(x) "multiPhylo" %in% x)
    if (!all(isphylo | ismulti)) {
        warning('some objects not of class "phylo" or "multiPhylo": argument recursive=TRUE ignored')
        return(obj)
    }
    for (i in which(isphylo)) obj[[i]] <- .c_phylo_single(obj[[i]])
    ## added by Klaus
    for (i in which(ismulti)) obj[[i]] <- .uncompressTipLabel(obj[[i]])
    .makeMultiPhyloFromObj(obj)
}`

const rtdal000124Source0021 = `.uncompressTipLabel <- function(x)
{
    Lab <- attr(x, "TipLabel")
    if (is.null(Lab)) return(x)
    clx <- class(x) # <- new
    class(x) <- NULL
    for (i in seq_along(x)) x[[i]]$tip.label <- Lab # <- modified
    class(x) <- clx # <- modified
    attr(x, "TipLabel") <- NULL
    x
}`

const rtdal000124Source0022 = "`[<-.multiPhylo` <- function(x, i, value)\n{\n    ## recycling is allowed so no need to check length(value) != length(i)\n    if (missing(i)) i <- seq_along(x)\n\n    ## check that all elements in 'value' inherit class \"phylo\"\n    test <- unlist(lapply(value, function(xx) !inherits(xx, \"phylo\")))\n    if (any(test))\n        stop(\"at least one element in 'value' is not of class \\\"phylo\\\".\")\n\n    oc <- oldClass(x)\n    class(x) <- NULL\n\n    TipLabel.x <- attr(x, \"TipLabel\")\n    TipLabel.value <- attr(value, \"TipLabel\")\n\n    if (is.null(TipLabel.x)) {\n        if (!is.null(TipLabel.value))           # to solve PR #45\n            value <- .uncompressTipLabel(value) #\n        x[i] <- value\n        class(x) <- oc\n        return(x)\n    }\n\n    ## to solve PR #45\n    if (is.null(TipLabel.value)) {\n        x <- .uncompressTipLabel(x)\n        class(x) <- NULL\n    } else {\n        if (!identical(TipLabel.x, TipLabel.value)) {\n            x <- .uncompressTipLabel(x)\n            class(x) <- NULL\n            value <- .uncompressTipLabel(value)\n        }\n    }\n\n    x[i] <- 0L # in case x needs to be elongated\n    class(x) <- oc\n    j <- 1L\n    for (k in i) {\n        ## x is of class \"multiPhylo\", so this uses the operator below:\n        x[[k]] <- value[[j]]\n        j <- j + 1L\n    }\n    x\n}"

const rtdal000124Source0023 = "`[[<-.multiPhylo` <- function(x, i, value)\n{\n    if (!inherits(value, \"phylo\"))\n        stop('trying to assign an object not of class \"phylo\" into an object of class \"multiPhylo\".')\n\n    oc <- oldClass(x)\n    class(x) <- NULL\n\n    Lab <- attr(x, \"TipLabel\")\n\n    if (!is.null(Lab)) {\n        n <- length(Lab)\n        if (n != length(value$tip.label))\n            stop(\"tree with different number of tips than those in the list (which all have the same labels; maybe you want to uncompress them)\")\n\n        o <- match(value$tip.label, Lab)\n        if (any(is.na(o)))\n            stop(\"tree tip labels do not match with those in the list; maybe you want to uncompress them.\")\n        value$tip.label <- NULL\n        ie <- match(o, value$edge[, 2])\n        value$edge[ie, 2] <- 1:n\n    }\n\n    x[[i]] <- value\n    class(x) <- oc\n    x\n}"

const rtdal000124Source0025 = `degree <- function(x, ...) UseMethod("degree")`

const rtdal000124Source0026 = `degree.phylo <- function(x, details = FALSE, ...)
{
    N <- max(x$edge)
    res <- tabulate(x$edge, N)
    if (details) return(res)
    tab <- tabulate(res)
    DF <- data.frame(Degree = seq_along(tab), N = tab)
    DF[tab > 0, ]
}`

const rtdal000124Source0027 = `degree.evonet <- function(x, details = FALSE, ...)
{
    N <- length(x$tip.label) + x$Nnode
    res <- tabulate(x$edge, N) + tabulate(x$reticulation, N)
    if (details) return(res)
    tab <- tabulate(res)
    DF <- data.frame(Degree = seq_along(tab), N = tab)
    DF[tab > 0, ]
}`

