const rtdal000174Source0068 = `dim(all.comb)      <- dim(all.id)      <-    c(from=length(all.types), to=length(all.types))`

const rtdal000174Source0069 = `dimnames(all.comb) <- dimnames(all.id) <- list(from= names(all.types), to= names(all.types))`

const rtdal000174Source0070 = `for (i in seq_along(all.types)) {
  for (j in seq_along(all.as)) {
    # coerce all types to all types (FROM -> TO)
    all.comb[[i, j]] <- all.as[[j]](all.types[[i]])
    # and test whether coercing back to the FROM type gives the orginal object
    all.id[i, j] <- identical(all.as[[i]](all.comb[[i, j]]),  all.types[[i]])
  }
}`

