const rtdal000177Source0015 = `names(booltypes) <- booltypes`

const rtdal000177Source0016 = `booltype <- function(x) {
  if (is.ri(x))
    booltypes[["ri"]]
  else if (is.hi(x))
    booltypes[["hi"]]
  else if (is.which(x))
    booltypes[["which"]]
  else if (is.bitwhich(x))
    booltypes[["bitwhich"]]
  else if (is.bit(x))
    booltypes[["bit"]]
  else if (is.logical(x))
    booltypes[["logical"]]
  else { # nolint: brace_linter.
    ret <- booltypes[["nobool"]]
    names(ret) <- typeof(x)
    ret
  }
}`

const rtdal000177Source0023 = `as.booltype.default <- function(x, booltype="logical", ...) {
  bt <- match.arg(as.character(booltype), as.character(booltypes))
  f = switch(bt,
    logical="as.logical",
    bit="as.bit",
    bitwhich="as.bitwhich",
    which="as.which",
    hi=stop("not implemented for booltype hi"),
    ri="as.ri"
  )
  do.call(f, c(list(x, ...)))
}`

