const rtdal000177Source0063 = `as.integer.bitwhich <- function(x, ...) {
  n <- length(x)
  if (is.logical(x)) {
    if (sum(x) == n)
      rep(1L, n)
    else
      rep(0L, n)
  } else {
    ret <- integer(n)
    ret[x] <- 1L
    ret
  }
}`

