const rtdal000177Source0084 = `as.bitwhich.logical <- function(x, poslength=NULL, ...) {
  maxindex <- length(x)
  if (maxindex == 0) return(bitwhich())
  if (is.null(poslength))
    poslength <- sum(x, na.rm=TRUE)
  else if (poslength > maxindex)
    stop("poslength > maxindex")
  if (poslength == 0)
    bitwhich(maxindex, FALSE, poslength=poslength)
  else if (poslength == maxindex)
    bitwhich(maxindex, TRUE, poslength=poslength)
  else if (poslength > maxindex %/% 2L)
    as.bitwhich(as.bit(x), poslength=poslength)
  else
    bitwhich(maxindex, which(x), poslength=poslength)
}`

const rtdal000177Source0085 = `as.bitwhich.bit <- function(x, range=NULL, poslength=NULL, ...) {
  maxindex <- length(x)
  if (!maxindex) return(bitwhich())
  if (is.null(range)) {
    range <- c(1L, maxindex)
  } else {
    range <- as.integer(range[1:2])
    if (range[1] < 1L || range[2] > maxindex)
      stop("illegal range")
  }
  if (is.null(poslength))
    poslength <- sum(x, range=range, na.rm=TRUE)
  else
    if (poslength > maxindex)
      stop("poslength > maxindex")
  if (poslength == 0)
    bitwhich(maxindex, FALSE, poslength=poslength)
  else if (poslength == maxindex)
    bitwhich(maxindex, TRUE, poslength=poslength)
  else if (poslength > maxindex %/% 2L) {
    bitwhich(maxindex,
      .Call(C_R_bit_which, x, maxindex - poslength, range=range, negative=TRUE),
      poslength=poslength
    )
  } else {
    bitwhich(maxindex,
      .Call(C_R_bit_which, x, poslength, range=range, negative=FALSE),
      poslength=poslength
    )
  }
}`

const rtdal000177Source0090 = "`!.bit` <- function(x) {\n  if (length(x)) {\n    ret <- copy_vector(x)\n    setattributes(ret, attributes(x))\n    .Call(C_R_bit_not, ret)\n  } else {\n    x\n  }\n}"

const rtdal000177Source0096 = "`!.bitwhich` <- function(x) {\n  n <- length(x)\n  p <- sum(x)\n  if (is.logical(x)) {\n    if (n == 0)\n      bitwhich()\n    else if (p == n) {\n      bitwhich(maxindex=n, FALSE, poslength=0L)\n    } else {\n      bitwhich(maxindex=n, TRUE, poslength=n)\n    }\n  } else {\n    bitwhich(maxindex=n,\n      copy_vector(x, revx=TRUE),\n      poslength=n - p,\n      is.unsorted = FALSE,\n      has.dup=FALSE\n    )\n  }\n}"

const rtdal000177Source0097 = "`&.bitwhich` <- function(e1, e2) {\n  e1 <- as.bitwhich(e1)\n  e2 <- as.bitwhich(e2)\n  n <- c(length(e1), length(e2))\n  if (any(n == 0L))\n    return(bitwhich())\n  if (n[1] != n[2])\n    stop(\"length(e1) != length(e2)\")\n  p <- c(sum(e1), sum(e2))\n  if (p[1] == 0 || p[2] == 0)\n    return(bitwhich(n[1], FALSE, 0L))\n  if (p[1] == n[1])\n    return(e2)\n  if (p[2] == n[2])\n    return(e1)\n  #negative <- p>(n %/% 2L)\n  negative <- c(unclass(e1)[1] < 0, unclass(e2)[1] < 0)\n  if (negative[1]) {\n    if (negative[2]) {\n      ret <- merge_union(e1, e2, method=\"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=n[1] - length(ret))\n    } else {\n      ret <- merge_setdiff(e2, e1, revy=TRUE, method=\"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=length(ret))\n    }\n  } else {\n    # nolint next: unnecessary_nesting_linter. Good parallelism.\n    if (negative[2]) {\n      ret <- merge_setdiff(e1, e2, revy=TRUE, method=\"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=length(ret))\n    } else {\n      ret <- merge_intersect(e1, e2, method=\"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=length(ret))\n    }\n  }\n}"

const rtdal000177Source0098 = "`|.bitwhich` <- function(e1, e2) {\n  e1 <- as.bitwhich(e1)\n  e2 <- as.bitwhich(e2)\n  n <- c(length(e1), length(e2))\n  if (any(n == 0L))\n    return(bitwhich())\n  if (n[1] != n[2])\n    stop(\"length(e1) != length(e2)\")\n  p <- c(sum(e1), sum(e2))\n  if (p[1] == n[1] || p[2] == n[2])\n    return(bitwhich(n[1], TRUE, n[1]))\n  if (p[1] == 0)\n    return(e2)\n  if (p[2] == 0)\n    return(e1)\n  #negative <- p>(n %/% 2L)\n  negative <- c(unclass(e1)[1] < 0, unclass(e2)[1] < 0)\n  if (negative[1]) {\n    if (negative[2]) {\n      ret <- merge_intersect(e1, e2, method=\"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=n[1] - length(ret))\n    } else {\n      ret <- merge_setdiff(e1, e2, revy=TRUE, method=\"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=n[1] - length(ret))\n    }\n  } else {\n    # nolint next: unnecessary_nesting_linter. Good parallelism.\n    if (negative[2]) {\n      ret <- merge_setdiff(e2, e1, revy=TRUE, method=\"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=n[1] - length(ret))\n    } else {\n      ret <- merge_union(e1, e2, method=\"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=length(ret))\n    }\n  }\n}"

const rtdal000177Source0099 = "`==.bitwhich` <- function(e1, e2) {\n  e1 <- as.bitwhich(e1)\n  e2 <- as.bitwhich(e2)\n  n <- c(length(e1), length(e2))\n  if (any(n == 0L))\n    return(bitwhich())\n  if (n[1] != n[2])\n    stop(\"length(e1) != length(e2)\")\n  p <- c(sum(e1), sum(e2))\n  if (p[1] == 0)\n    return(!e2)\n  if (p[1] == n[1])\n    return(e2)\n  if (p[2] == 0)\n    return(!e1)\n  if (p[2] == n[2])\n    return(e1)\n  #negative <- p>(n %/% 2L)\n  negative <- c(unclass(e1)[1] < 0, unclass(e2)[1] < 0)\n  if (negative[1]) {\n    if (negative[2]) {\n      ret <- merge_symdiff(e1, e2, method = \"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=n[1] - length(ret))\n    } else {\n      ret <- merge_symdiff(e1, e2, revx=TRUE, method = \"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=length(ret))\n    }\n  } else {\n    # nolint next: unnecessary_nesting_linter. Good parallelism.\n    if (negative[2]) {\n      ret <- merge_symdiff(e1, e2, revy=TRUE, method = \"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=length(ret))\n    } else {\n      ret <- merge_symdiff(e1, e2, revx=TRUE, revy=TRUE, method = \"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=n[1] - length(ret))\n    }\n  }\n}"

const rtdal000177Source0100 = "`!=.bitwhich` <- function(e1, e2) {\n  e1 <- as.bitwhich(e1)\n  e2 <- as.bitwhich(e2)\n  n <- c(length(e1), length(e2))\n  if (any(n == 0L))\n    return(bitwhich())\n  if (n[1] != n[2])\n    stop(\"length(e1) != length(e2)\")\n  p <- c(sum(e1), sum(e2))\n  if (p[1] == 0)\n    return(e2)\n  if (p[1] == n[1])\n    return(!e2)\n  if (p[2] == 0)\n    return(e1)\n  if (p[2] == n[2])\n    return(!e1)\n  #negative <- p>(n %/% 2L)\n  negative <- c(unclass(e1)[1] < 0, unclass(e2)[1] < 0)\n  if (negative[1]) {\n    if (negative[2]) {\n      ret <- merge_symdiff(e1, e2, revx=TRUE, revy=TRUE, method = \"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=length(ret))\n    } else {\n      ret <- merge_symdiff(e1, e2, revy=TRUE, method = \"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=n[1] - length(ret))\n    }\n  } else {\n    # nolint next: unnecessary_nesting_linter. Good parallelism.\n    if (negative[2]) {\n      ret <- merge_symdiff(e1, e2, revx=TRUE, method = \"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=n[1] - length(ret))\n    } else {\n      ret <- merge_symdiff(e1, e2, method = \"exact\")\n      bitwhich(maxindex=n[1], ret, poslength=length(ret))\n    }\n  }\n}"

const rtdal000177Source0102 = "`&.booltype` <- function(e1, e2) {\n  # align booltype between logical and bitwhich\n  b1 <- booltype(e1)\n  b2 <- booltype(e2)\n  b <- min(max(booltypes[[\"logical\"]], min(b1, b2)), booltypes[[\"bitwhich\"]])\n  e1 <- as.booltype(e1, b)\n  e2 <- as.booltype(e2, b)\n  # align length\n  n1 <- length(e1)\n  n2 <- length(e2)\n  if (n1 && n2) {\n    if (n1 < n2) {\n      if (n2 %% n1)\n        warning(\"longer object length is not a multiple of shorter object length\")\n      e1 <- rep(e1, length.out=n2)\n      n1 <- n2\n    } else if (n2 < n1) {\n      if (n1 %% n2)\n        warning(\"longer object length is not a multiple of shorter object length\")\n      e2 <- rep(e2, length.out=n1)\n    }\n  }\n  # do the operation\n  switch(as.character(b),\n    logical = e1 & e2,\n    bit = \"&.bit\"(e1, e2),\n    bitwhich = \"&.bitwhich\"(e1, e2)\n  )\n}"

const rtdal000177Source0103 = "`|.booltype` <- function(e1, e2) {\n  # align booltype between logical and bitwhich\n  b1 <- booltype(e1)\n  b2 <- booltype(e2)\n  b <- min(max(booltypes[[\"logical\"]], min(b1, b2)), booltypes[[\"bitwhich\"]])\n  e1 <- as.booltype(e1, b)\n  e2 <- as.booltype(e2, b)\n  # align length\n  n1 <- length(e1)\n  n2 <- length(e2)\n  if (n1 && n2) {\n    if (n1 < n2) {\n      if (n2 %% n1)\n        warning(\"longer object length is not a multiple of shorter object length\")\n      e1 <- rep(e1, length.out=n2)\n      n1 <- n2\n    } else if (n2 < n1) {\n      if (n1 %% n2)\n        warning(\"longer object length is not a multiple of shorter object length\")\n      e2 <- rep(e2, length.out=n1)\n    }\n  }\n  # do the operation\n  switch(as.character(b),\n    logical = e1 | e2,\n    bit = \"|.bit\"(e1, e2),\n    bitwhich = \"|.bitwhich\"(e1, e2)\n  )\n}"

const rtdal000177Source0104 = "`==.booltype` <- function(e1, e2) {\n  # align booltype between logical and bitwhich\n  b1 <- booltype(e1)\n  b2 <- booltype(e2)\n  b <- min(max(booltypes[[\"logical\"]], min(b1, b2)), booltypes[[\"bitwhich\"]])\n  e1 <- as.booltype(e1, b)\n  e2 <- as.booltype(e2, b)\n  # align length\n  n1 <- length(e1)\n  n2 <- length(e2)\n  if (n1 && n2) {\n    if (n1 < n2) {\n      if (n2 %% n1)\n        warning(\"longer object length is not a multiple of shorter object length\")\n      e1 <- rep(e1, length.out=n2)\n      n1 <- n2\n    } else if (n2 < n1) {\n      if (n1 %% n2)\n        warning(\"longer object length is not a multiple of shorter object length\")\n      e2 <- rep(e2, length.out=n1)\n    }\n  }\n  # do the operation\n  switch(as.character(b),\n    logical = e1 == e2,\n    bit = \"==.bit\"(e1, e2),\n    bitwhich = \"==.bitwhich\"(e1, e2)\n  )\n}"

const rtdal000177Source0105 = "`!=.booltype` <- function(e1, e2) {\n  # align booltype between logical and bitwhich\n  b1 <- booltype(e1)\n  b2 <- booltype(e2)\n  b <- min(max(booltypes[[\"logical\"]], min(b1, b2)), booltypes[[\"bitwhich\"]])\n  e1 <- as.booltype(e1, b)\n  e2 <- as.booltype(e2, b)\n  # align length\n  n1 <- length(e1)\n  n2 <- length(e2)\n  if (n1 && n2) {\n    if (n1 < n2) {\n      if (n2 %% n1)\n        warning(\"longer object length is not a multiple of shorter object length\")\n      e1 <- rep(e1, length.out=n2)\n      n1 <- n2\n    } else if (n2 < n1) {\n      if (n1 %% n2)\n        warning(\"longer object length is not a multiple of shorter object length\")\n      e2 <- rep(e2, length.out=n1)\n    }\n  }\n  # do the operation\n  switch(as.character(b),\n    logical = e1 != e2,\n    bit = \"!=.bit\"(e1, e2),\n    bitwhich = \"!=.bitwhich\"(e1, e2)\n  )\n}"

const rtdal000177Source0108 = `all.bit <- function(x, range=NULL, ...) {
  if (is.null(range)) {
    range <- c(1L, length(x))
  } else {
    range <- as.integer(range[1:2])
    if (range[1] < 1L || range[2] > length(x))
      stop("illegal range")
  }
  .Call(C_R_bit_all, x, range)
}`

