const rtdal000177Source0114 = `range.bit <- function(x, range=NULL, ...) {
  if (is.null(range)) {
    range <- c(1L, length(x))
  } else {
    range <- as.integer(range[1:2])
    if (range[1] < 1L || range[2] > length(x))
      stop("illegal range")
  }
  ret <- integer(2)
  ret[1] <- .Call(C_R_bit_min, x, range)
  if (is.na(ret[1]))
    ret[2] <- NA_integer_
  else
    ret[2] <- .Call(C_R_bit_max, x, range)
  ret
}`

const rtdal000177Source0115 = "summary.bit <- function(object, range=NULL, ...) {\n  if (is.null(range)) {\n    range <- c(1L, length(object))\n  } else {\n    range <- as.integer(range[1:2])\n    if (range[1] < 1L || range[2] > length(object))\n      stop(\"illegal range\")\n  }\n  s <- sum(object, range=range)\n  r <- range(object, range=range)\n  c(`FALSE`=range[2] - range[1] + 1L - s, `TRUE`=s, Min.=r[1], Max.=r[2])\n}"

const rtdal000177Source0116 = `all.bitwhich <- function(x, range=NULL, ...) {
  if (is.null(range)) return(attr(x, "poslength") == attr(x, "maxindex"))
  y <- bitwhich_representation(x)
  range <- as.integer(range)
  if (is.logical(y)) {
    if (y)
      TRUE
    else
      FALSE
  } else if (y < 0) {
    all(merge_rangenotin(rx=range, y=x, revx=FALSE, revy=TRUE))
  } else {
    all(merge_rangein(rx=range, y=x, revx=FALSE, revy=FALSE))
  }
}`

