const rtdal000178Source0009 = `bit_sort_unique <- function(x, decreasing = FALSE, na.last=NA, has.dup=TRUE, range_na=NULL) {
  if (!(is.integer(x) || is.factor(x)))
    stop("x must be integer (or factor)")
  if (is.null(range_na))
    range_na <- range_na(x)
  else
    range_na <- as.integer(range_na)
  if (is.na(range_na[1])) {
    if (is.na(na.last) || length(range_na) < 3L || range_na[3] == 0)
      return(integer())
    else
      return(NA_integer_)
  }
  nr <- as.double(range_na[2]) - as.double(range_na[1]) + 1
  d <- length(x) / nr
  if (nr > .Machine$integer.max || d < 0) {
    if (has.dup) {
      ret <- quicksort3(x, na.last = xor(na.last, decreasing))
      ret <- merge_unique(ret)
    } else {
      ret <- quicksort2(x, na.last = xor(na.last, decreasing))
    }
    if (decreasing)
      reverse_vector(ret)
    else
      ret
  } else {
    .Call(C_R_bit_sort_unique,
      tmp=bit(nr), x, range_na,
      as.logical(na.last),
      as.logical(decreasing)
    )
  }
}`

const rtdal000178Source0012 = `bit_unique <- function(x, na.rm = NA, range_na=NULL) {
  na.rm <- as.logical(na.rm)
  if (!(is.integer(x) || is.factor(x)))
    stop("x must be integer (or factor)")
  if (!length(x))
    return(x)
  if (is.null(range_na))
    range_na <- range_na(x)
  else
    range_na <- as.integer(range_na)
  if (is.na(range_na[1])) {
    if (is.na(na.rm)) {
      return(NA_integer_)
    } else if (na.rm) {
      return(integer())
    } else {
      return(rep(NA_integer_, range_na[3]))
    }
  }
  nr <- as.double(range_na[2]) - as.double(range_na[1]) + 1
  d <- length(x) / nr
  if (nr > .Machine$integer.max || d < 1 / 64) {
    if (is.na(na.rm)) {
      unique(x, incomparables = FALSE)
    } else if (na.rm) {
      x <- unique(x, incomparables = FALSE)
      x <- x[!is.na(x)]
      x
    } else {
      unique(x, incomparables = NA)
    }
  } else {
    .Call(C_R_bit_unique, tmp=bit(nr), x, range_na, na.rm)
  }
}`

const rtdal000178Source0014 = `bit_anyDuplicated <- function(x, na.rm = NA, range_na=NULL) {
  na.rm <- as.logical(na.rm)
  if (!(is.integer(x) || is.factor(x)))
    stop("x must be integer (or factor)")
  if (!length(x))
    return(0L)
  if (is.null(range_na))
    range_na <- range_na(x)
  else
    range_na <- as.integer(range_na)
  if (is.na(range_na[1]))
    nr <- 0L  # no numbers, no temp bit vector
  else
    nr <- as.double(range_na[2]) - as.double(range_na[1]) + 1
  d <- length(x) / nr
  if (nr > .Machine$integer.max || d < 1 / 64) {
    if (is.na(na.rm)) {
      anyDuplicated(x, incomparables = FALSE)
    } else if (na.rm) {
      max(0L, min(anyDuplicated(x, incomparables = NA), firstNA(x)))
    } else {
      anyDuplicated(x, incomparables = NA)
    }
  } else {
    .Call(C_R_bit_anyDuplicated, bit(nr), x, range_na=range_na, as.logical(na.rm))
  }
}`

const rtdal000178Source0015 = `bit_sumDuplicated <- function(x, na.rm = NA, range_na=NULL) {
  if (!(is.integer(x) || is.factor(x)))
    stop("x must be integer (or factor)")
  if (!length(x))
    return(0L)
  if (is.null(range_na))
    range_na <- range_na(x)
  else
    range_na <- as.integer(range_na)
  if (is.na(range_na[1]))
    nr <- 0L  # no numbers, no temp bit vector
  else
    nr <- as.double(range_na[2]) - as.double(range_na[1]) + 1
  d <- length(x) / nr
  if (nr > .Machine$integer.max || d < 1 / 64) {
    if (is.na(na.rm)) {
      sum(duplicated(x, incomparables = FALSE))
    } else if (na.rm) {
      sum(duplicated(x, incomparables = NA)) + sum(is.na(x))
    } else {
      sum(duplicated(x, incomparables = NA))
    }
  } else {
    .Call(C_R_bit_sumDuplicated, bit(nr), x, range_na=range_na, as.logical(na.rm))
  }
}`

const rtdal000178Source0022 = `bit_rangediff <- function(rx, y, revx=FALSE, revy=FALSE) {
  if (!is.integer(y))
    stop("y must be integer")
  if (!is.ri(rx)) {
    stopifnot(length(rx) == 2)
    rx <- as.integer(rx)
  }
  if (rx[1] > rx[2])
    ox <- as.double(rev(rx))
  else
    ox <- as.double(rx)
  n <- ox[2] - ox[1] + 1L
  d <- length(y) / n
  if (n > .Machine$integer.max || d < 1 / 64) {
    ox <- as.integer(ox)
    y <- .Call(C_R_int_quicksort2, copy_vector(y), c(ox, 0L), na.last=NA)
    ret <- merge_rangediff(ox, y, revx=revx, revy=revy)
    if (rx[1] > rx[2])
      ret <- rev(ret)
    ret
  } else {
    .Call(C_R_bit_rangediff, tmp=bit(n), as.integer(rx), y, as.logical(revx), as.logical(revy))
  }
}`

