const rtdal000179Source0002 = `repfromto <- function(x, from, to) {
  nx <- length(x)
  if (!nx) {
    return(NA[from:to])
  }
  from <- as.integer(from)
  to <- as.integer(to)
  if (to > nx) {
    N <- to - from + 1L
    from <- (from - 1L) %% nx + 1L
    to <- to %% nx
    # NOTE: fetch in sequence pre-main-post in case is.ff(x)
    if (from <= to && N < nx) {
      ret <- x[from:to]
    } else {
      pre <- x[from:nx]
      nrep <- (N - length(pre) - to) %/% nx
      main <- if (nrep) rep(x[1:nx], nrep)
      post <- if (to) x[1:to]
      ret <- c(pre, main, post)
    }
  } else {
    ret <- x[from:to]
  }
  a <- attributes(x[1])
  a$names <- NULL
  attributes(ret) <- a
  ret
}`

const rtdal000179Source0005 = `if (FALSE) {
  intseq <- function(from=NULL, to=NULL, by=NULL, length.out=NULL, along.with=NULL) {
    if (is.null(from)) {
      if (is.null(to))
        stop("need 'from' or 'to'")
      else
        to <- as.integer(to)
      if (is.null(by))
        by <- 1L
      else
        by <- as.integer(by)
    } else {
      from <- as.integer(from)
      if (is.null(to)) {
        if (is.null(by))
          by <- 1L
        else
          by <- as.integer(by)
      } else {
        to <- as.integer(to)
        n <- to - from
        if (is.null(by)) {
          if (to < from)
            by = -1L
          else
            by = 1L
        } else {
          by <- as.integer(by)
          if (!n) return(from) # to == from
          if (sign(n) != sign(by))
            stop("wrong sign of by")
        }
      }
    }

    if (is.null(length.out)) {
      if (is.null(along.with)) {
        if (is.null(to) || is.null(from))
          stop("not enough info to guess the length.out")
        length.out <- n %/% by + 1L
      } else {
        length.out <- length(along.with)
      }
    } else {
      length.out <- as.integer(length.out)
    }
    if (length.out) {
      if (length.out == 1L)
        from
      else
        cumsum(c(from, rep(by, length.out - 1L)))
    } else {
      integer()
    }
  }
}`

const rtdal000179Source0006 = `chunks <- function(
  from = NULL,
  to = NULL,
  by = NULL,
  length.out = NULL,
  along.with = NULL,
  overlap = 0L,
  method=c("bbatch", "seq"),
  maxindex = NA
) {
  method <- match.arg(method)
  if (!is.null(along.with)) {
    if (is.null(from))
      from <- 1L
    else if (length(from) == 1)
      from <- as.integer(from)
    else
      stop("'from' must be scalar")
    if (is.null(to))
      to <- length(along.with)
    else if (length(to) == 1)
      to <- as.integer(to)
    else
      stop("'to' must be scalar")
  }
  if (length(from) == 1)
    from <- as.integer(from)
  else
    stop("'from' must be scalar")
  if (length(to) == 1)
    to <- as.integer(to)
  else
    stop("'to' must be scalar")

  if (to < from)
    stop("to < from")
  N <- to - from + 1L

  if (is.null(by)) {
    if (is.null(length.out))
      stop("need either 'by' or 'length.out'")
    if (length(length.out) != 1L)
      stop("'length.out' must be scalar")
    length.out <- as.integer(length.out)
    if (length.out > N)
      length.out <- N
    by <- N %/% length.out
  } else if (length(by) == 1) {
    by <- as.integer(by)
    if (by < 1)
      stop("'by' must be > 0")
    length.out <- (N - 1L) %/% by + 1L
  } else {
    stop("'by' must be scalar")
  }

  if (method == "bbatch")
    by <- as.integer(bbatch(N, by)$b)

  if (length.out > 1L) {
    from <- cumsum(c(from, rep(by, length.out - 1L)))
    to <- c(from[-1], from[1] + N) - 1L  # fixed by Edwin de Jonge, 18.1.2011
    if (overlap > 0)
      from[-1] <- from[-1] - overlap
  }
  n <- length(from)
  s <- seq_len(n)
  ret <- vector("list", n)
  for (i in s) {
    ret[[i]] <- ri(from[i], to[i], maxindex)
  }
  names(ret) <- paste(from, to, sep=":")
  ret
}`

const rtdal000179Source0007 = `chunk <- function(x = NULL, ...) {
  if (is.null(x))
    return(chunks(...))
  UseMethod("chunk")
}`

const rtdal000179Source0008 = `chunk.default <- function(x = NULL, ..., RECORDBYTES = NULL, BATCHBYTES = NULL) {
  if (is.null(BATCHBYTES)) {
    BATCHBYTES <- getOption("ffbatchbytes", 16777216L)
  }
  if (is.null(RECORDBYTES)) {
    if (isNamespaceLoaded("ff"))
      RECORDBYTES = ff::.rambytes[ff::vmode(x)]
    else
      RECORDBYTES =
        switch(typeof(x), raw=1L, character=4L, logical=4L, integer=4L, double=8L, complex=16L)
  }
  RECORDBYTES <- sum(RECORDBYTES)
  if (is.na(RECORDBYTES) || RECORDBYTES == 0L)
    stop("RECORDBYTES not above zero, probably due to unknown type resp. vmode")
  n <- length(x)
  if (n) {
    l <- list(...)
    if (is.null(l$from))
      l$from <- 1L
    if (is.null(l$to))
      l$to <- n
    if (is.null(l$by) && is.null(l$len)) {
      b <- pmin(BATCHBYTES %/% RECORDBYTES, .Machine$integer.max)
      if (b == 0L) {
        b <- 1L
        warning("single record does not fit into BATCHBYTES")
      }
      l$by <- b
    }
    l$maxindex <- n
    ret <- do.call("chunks", l)
  } else {
    ret <- list()
  }
  ret
}`

const rtdal000179Source0009 = `vecseq <- function(x, y=NULL, concat=TRUE, eval=TRUE) {
  if (missing(y)) {
    y <- x
    x <- 1L
  }
  if (concat) {
    if (eval) {
      # pure R version was: eval(parse(text=paste("c(", paste(x, y, sep=":", collapse=", "), ")")))
      # now calling C-code
      nx <- length(x)
      ny <- length(y)
      if (nx < ny)
        x <- rep(as.integer(x), length.out=ny)
      if (ny < nx)
        y <- rep(as.integer(y), length.out=nx)
      .Call(C_R_bit_vecseq, as.integer(x),  as.integer(y))
    } else {
      parse(text=paste("c(", paste(x, y, sep=":", collapse=", "), ")"))[[1]]
    }
  } else {
    # nolint next: unnecessary_nesting_linter. Good parallelism.
    if (eval)
      eval(parse(text=paste("list(", paste(x, y, sep=":", collapse=", "), ")")))
    else
      as.list(parse(text=paste(x, y, sep=":")))
  }
}`

