const rtdal000200Source0007 = "`%*%.integer64` = function(x, y) {\n  if (!is.integer64(x) && !is.integer64(y)) {\n    stop(\"internal error in %*%.integer64: neither x nor y is integer64\") # nocov\n  }\n\n  target_class = target_class_for_Ops(x, y)\n  if (target_class %in% c(\"character\", \"factor\")) {\n    stop(errorCondition(\n      gettext(\"requires numeric/complex matrix/vector arguments\", domain=\"R\"),\n      call=sys.call(sys.nframe() - 1L)\n    ))\n  }\n  if (target_class != \"integer64\") {\n    if (is.integer64(x)) {\n      for (cc in class(y)) {\n        f = getS3method(\"%*%\", cc, optional=TRUE)\n        if (!is.null(f))\n          return(f(.as_double_integer64(x, keep.attributes=TRUE), y))\n      }\n      x = .as_double_integer64(x, keep.attributes=TRUE)\n    } else {\n      y = .as_double_integer64(y, keep.attributes=TRUE)\n    }\n    return(x%*%y)\n  }\n\n  dx = dim(x)\n  dy = dim(y)\n  if (length(dx) > 2L || length(dy) > 2L)\n    stop(\"non-conformable arguments\", domain=\"R\")\n  if (length(dx) <= 1L && length(dy) <= 1L) {\n    dx = c(1L, length(x))\n    if (length(x) == length(y)) {\n      dy = c(length(y), 1L)\n    } else {\n      dy = c(1L, length(y))\n    }\n  }\n  if (length(dx) <= 1L)\n    dx = c(1L, dy[1L])\n  if (length(dy) <= 1L)\n    dy = c(dx[2L], 1L)\n  if (dx[2L] != dy[1L])\n    stop(\"non-conformable arguments\", domain=\"R\")\n  dim(x) = dx\n  dim(y) = dy\n\n  # nolint start: undesirable_function_linter.\n  if (is.double(x)) {\n    ret = .Call(C_matmult_double_integer64, x, structure(as.integer64(y), dim=dy), double(dx[1L]*dy[2L]))\n  } else if (is.double(y)) {\n    ret = .Call(C_matmult_integer64_double, structure(as.integer64(x), dim=dx), y, double(dx[1L]*dy[2L]))\n  } else {\n    ret = .Call(\n      C_matmult_integer64_integer64,\n      structure(as.integer64(x), dim=dx),\n      structure(as.integer64(y), dim=dy),\n      double(dx[1L]*dy[2L])\n    )\n  }\n  # nolint end: undesirable_function_linter.\n  dim(ret) = c(dx[1L], dy[2L])\n  oldClass(ret) = \"integer64\"\n  ret\n}"

const rtdal000200Source0008 = `as.matrix.integer64 = function(x, ...) {
  if (is.matrix(x)) {
    x
  } else {
    array(x, c(length(x), 1L), if (!is.null(names(x))) list(names(x), NULL))
  }
}`

