const rtdal000203Source0001 = `union = function(x, y) {
  if (!(is.integer64(x) || is.integer64(y)))
    return(base::union(x, y))

  target_class = target_class(list(x, y))
  # try using the benefit of integer64 caching, if possible. I.e. call unique() before as().
  x = unique(x)
  class_x = class(x)[1L]
  if (class_x != target_class) {
    # TODO(#44): remove this special coercion for factor and ordered
    if (
      target_class == "integer64"
      && class_x %in% c("factor", "ordered")
      && isFALSE(getOption("bit64.promoteInteger64ToCharacter", FALSE))
    )
      x = as.character(x)
    x = as(x, target_class)
  }
  y = unique(y)
  class_y = class(y)[1L]
  if (class_y != target_class) {
    # TODO(#44): remove this special coercion for factor and ordered
    if (
      target_class == "integer64"
      && class_y %in% c("factor", "ordered")
      && isFALSE(getOption("bit64.promoteInteger64ToCharacter", FALSE))
    )
      y = as.character(y)
    y = as(y, target_class)
  }

  unique(c(x, y))
}`

const rtdal000203Source0002 = `intersect = function(x, y) {
  if (is.null(x) || is.null(y)) return(NULL)
  if (!(is.integer64(x) || is.integer64(y)))
    return(base::intersect(x, y))

  target_class = target_class(list(x, y))
  x = unique(x)
  class_x = class(x)[1L]
  if (class_x != target_class) {
    # TODO(#44): remove this special coercion for factor and ordered
    if (
      target_class == "integer64"
      && class_x %in% c("factor", "ordered")
      && isFALSE(getOption("bit64.promoteInteger64ToCharacter", FALSE))
    )
      x = as.character(x)
    x = as(x, target_class)
  }
  y = unique(y)
  class_y = class(y)[1L]
  if (class_y != target_class) {
    # TODO(#44): remove this special coercion for factor and ordered
    if (
      target_class == "integer64"
      && class_y %in% c("factor", "ordered")
      && isFALSE(getOption("bit64.promoteInteger64ToCharacter", FALSE))
    )
      y = as.character(y)
    y = as(y, target_class)
  }

  x[match(x, y, 0L) > 0L]
}`

const rtdal000203Source0003 = `setequal = function(x, y) {
  if (!(is.integer64(x) || is.integer64(y)))
    return(base::setequal(x, y))

  x = unique(x)
  y = unique(y)
  length_x = length(x)
  length_y = length(y)
  if (length_x != length_y) return(FALSE)
  if (length_x + length_y == 0L) return(TRUE)

  target_class = target_class(list(x, y))
  if (class(x)[1L] != target_class)
    x = as(x, target_class)
  if (class(y)[1L] != target_class)
    y = as(y, target_class)

  !anyNA(match(x, y))
}`

const rtdal000203Source0004 = `setdiff = function(x, y) {
  if (!(is.integer64(x) || is.integer64(y)))
    return(base::setdiff(x, y))

  class_x = class(x)[1L]
  if (class_x %in% c("POSIXct", "Date"))
    x = unclass(x)
  if (class_x %in% c("factor", "ordered"))
    x = as.character(x)
  target_class = target_class(list(x, y))
  x = unique(x)
  if (class(x)[1L] != target_class)
    x_match = as(x, target_class)
  else
    x_match = x
  y = unique(y)
  class_y = class(y)[1L]
  if (class_y != target_class) {
    # TODO(#44): remove this special coercion for factor and ordered
    if (
      target_class == "integer64"
      && class_y %in% c("factor", "ordered")
      && isFALSE(getOption("bit64.promoteInteger64ToCharacter", FALSE))
    )
      y = as.character(y)
    y = as(y, target_class)
  }

  x[match(x_match, y, 0L) == 0L]
}`

const rtdal000203Source0005 = `is.element = function(el, set) {
  if (!(is.integer64(el) || is.integer64(set)))
    return(base::is.element(el, set))

  target_class = target_class(list(el, set))
  class_el = class(el)[1L]
  if (class_el != target_class) {
    # TODO(#44): remove this special coercion for factor and ordered
    if (
      target_class == "integer64"
      && class_el %in% c("factor", "ordered")
      && isFALSE(getOption("bit64.promoteInteger64ToCharacter", FALSE))
    )
      el = as.character(el)
    el = as(el, target_class)
  }
  set = unique(set)
  class_set = class(set)[1L]
  if (class_set != target_class) {
    # TODO(#44): remove this special coercion for factor and ordered
    if (
      target_class == "integer64"
      && class_set %in% c("factor", "ordered")
      && isFALSE(getOption("bit64.promoteInteger64ToCharacter", FALSE))
    )
      set = as.character(set)
    set = as(set, target_class)
  }

  match(el, set, 0L) > 0L
}`

