const rtdal000205Source0005 = `sortfin = function(sorted, x, ...) UseMethod("sortfin")`

const rtdal000205Source0006 = `sortfin.integer64 = function(sorted, x, method=NULL, ...) {
  n = length(x)
  if (is.null(method)) {
    if (n < 2048L) {
      method = 1L
    } else if (n < length(sorted) / 128L) {
      method = 2L
    } else {
      method = 3L
    }
  } else {
    method = as.integer(method)
  }
  if (method == 1L) {
    .Call(C_r_ram_integer64_sortfin_asc
    , x=as.integer64(x)
    , sorted=as.integer64(sorted)
    , method=method
    , ret=logical(n)
    )
  } else {
    sx = clone(as.integer64(x))
    o = seq_along(x)
    ramsortorder(sx, o, na.last=FALSE, ...)
    ret = logical(n)
    ret[o] = .Call(C_r_ram_integer64_sortfin_asc
      , x=sx
      , sorted=as.integer64(sorted)
      , method=method
      , ret=ret
      )
    ret
  }
}`

