const rtdal000212Source0012 = `test_that("our overwrite of table() is consistent with base::table", {
  expect_identical(table(NULL), base::table(NULL))
  expect_identical(table(a=NULL), base::table(a=NULL))
  expect_identical(table(NULL, NULL), base::table(NULL, NULL))
  expect_identical(table(a=NULL, b=NULL), base::table(a=NULL, b=NULL))
  expect_identical(table(integer(), NULL), base::table(integer(), NULL))
  expect_identical(table(a=integer(), b=NULL), base::table(a=integer(), b=NULL))
  expect_same_error(table(1L, NULL), base::table(1L, NULL))
  expect_same_error(table(a=1L, b=NULL), base::table(a=1L, b=NULL))

  skip_unless_r("> 3.5.0") # unclear what's going on
  expected_result = withr::with_seed(1L, base::table(
    exclude = sample.int(10L, 1L),
    useNA = sample(c("no", "ifany", "always"), 1L),
    deparse.level = sample.int(2L, 1L),
    sample.int(10L)
  ))
  expect_identical(
    withr::with_seed(1L, table(
      exclude = sample.int(10L, 1L),
      useNA = sample(c("no", "ifany", "always"), 1L),
      deparse.level = sample.int(2L, 1L),
      sample(as.integer64(1:10))
    )),
    expected_result
  )
  expect_identical(
    withr::with_seed(1L, table(
      exclude = sample.int(10L, 1L),
      useNA = sample(c("no", "ifany", "always"), 1L),
      deparse.level = sample.int(2L, 1L),
      sample.int(10L)
    )),
    expected_result
  )

  expected_result = withr::with_seed(1L, base::table(
    exclude = sample.int(10L, 1L),
    deparse.level = sample.int(2L, 1L),
    sample.int(10L)
  ))
  expect_identical(
    withr::with_seed(1L, table(
      exclude = sample.int(10L, 1L),
      deparse.level = sample.int(2L, 1L),
      sample(as.integer64(1:10))
    )),
    expected_result
  )
  expect_identical(
    withr::with_seed(1L, table(
      exclude = sample.int(10L, 1L),
      deparse.level = sample.int(2L, 1L),
      sample.int(10L)
    )),
    expected_result
  )

  expected_result = withr::with_seed(1L, base::table(
    exclude = sample.int(10L, 1L),
    useNA = sample(c("no", "ifany", "always"), 1L),
    sample.int(10L)
  ))
  expect_identical(
    withr::with_seed(1L, table(
      exclude = sample.int(10L, 1L),
      useNA = sample(c("no", "ifany", "always"), 1L),
      sample(as.integer64(1:10))
    )),
    expected_result
  )
  expect_identical(
    withr::with_seed(1L, table(
      exclude = sample.int(10L, 1L),
      useNA = sample(c("no", "ifany", "always"), 1L),
      sample.int(10L)
    )),
    expected_result
  )

  expected_result = withr::with_seed(1L, base::table(useNA=sample(c("no", "ifany", "always"), 1L), sample.int(10L)))
  expect_identical(
    withr::with_seed(1L, table(useNA=sample(c("no", "ifany", "always"), 1L), sample(as.integer64(1:10)))),
    expected_result
  )
  expect_identical(
    withr::with_seed(1L, table(useNA=sample(c("no", "ifany", "always"), 1L), sample.int(10L))),
    expected_result
  )
})`

