const rtdal000213Source0037 = `test_that("factor and order for integer64 are still necessary", {
  skip_unless_r(">= 4.1.0") # skip implementing "expect_failure" for ancient R
  skip_on_cran()
  skip_on_covr() # covr edits the function bodies

  x = c(132724613L, -2143220989L, -1L, NA, 1L)
  expect_failure(expect_identical(base::factor(as.integer64(x)), base::factor(x)))
  expect_failure(expect_identical(factor(as.integer64(x)), base::factor(as.integer64(x))))
  expect_identical(factor(as.integer64(x)), base::factor(x))

  expect_identical(formals(factor), formals(base::factor))
  expect_identical(formals(ordered), formals(base::ordered))
  expect_identical(body(ordered), body(base::ordered))

  x_named = as.integer64(1:2)
  names(x_named) = c("a", "b")
  expect_named(factor(x_named), c("a", "b"))
})`

const rtdal000213Source0038 = `with_parameters_test_that("factor and order work analogously to integer:", {
    x = c(132724613L, -2143220989L, -1L, NA, 1L)
    # as of now <4000 and >= 4000 test different code paths
    if (isTRUE(long_input))
      x = rep_len(x, 5000L)

    expect_identical(factor(as.integer64(x)), factor(x))

    expect_identical(
      tryCatch(
        factor(as.integer64(x), levels=levels, labels=labels, exclude=exclude, ordered=ordered),
        error = conditionMessage
      ),
      tryCatch(
        factor(x, levels=levels, labels=labels, exclude=exclude, ordered=ordered),
        error = conditionMessage
      )
    )
    if (isTRUE(ordered))
      expect_identical(
        tryCatch(ordered(as.integer64(x), levels=levels, labels=labels, exclude=exclude), error=conditionMessage),
        tryCatch(ordered(x, levels=levels, labels=labels, exclude=exclude), error=conditionMessage)
      )
},
  .cases = expand.grid(
      levels=I(list(NULL, NA, 1L, c(-1L, 1L), "1")),
      labels=I(list(levels, NULL, letters[1L], letters[1:2])),
      exclude=I(list(NULL, NA, 1L, c(-1L, 1L))),
      ordered=c(TRUE, FALSE),
      long_input=c(FALSE, TRUE)
    )
)`

const rtdal000213Source0039 = `test_that("factor() overwrite doesn't oversample (#274)", {
  expect_identical(
    withr::with_seed(1L, factor(sample.int(10L))),
    withr::with_seed(1L, base::factor(sample.int(10L)))
  )
  expected_result = withr::with_seed(1L, base::factor(exclude = sample.int(10L, 1L), sample.int(10L)))
  expect_identical(
    withr::with_seed(1L, factor(exclude = sample.int(10L, 1L), sample(as.integer64(1:10)))),
    expected_result
  )
  expect_identical(
    withr::with_seed(1L, factor(exclude = sample.int(10L, 1L), sample.int(10L))),
    expected_result
  )

  expected_result = withr::with_seed(1L, base::factor(sample.int(10L), exclude = sample.int(10L, 1L)))
  expect_identical(
    withr::with_seed(1L, factor(sample(as.integer64(1:10)), exclude = sample.int(10L, 1L))),
    expected_result
  )
  expect_identical(
    withr::with_seed(1L, factor(sample.int(10L), exclude = sample.int(10L, 1L))),
    expected_result
  )
})`

const rtdal000213Source0040 = "test_that(\"extraction works consistent to integer: vector[\", {\n  x = 1:10\n  names(x) = letters[seq_along(x)]\n  y = as.integer64(x)\n  names(y) = letters[seq_along(y)]\n\n  expect_identical(y[drop=FALSE], y)\n\n  sel = c(TRUE, FALSE, NA, TRUE)\n  expect_identical(y[sel], setNames(as.integer64(x[sel]), names(x)[sel]))\n\n  sel = c(1L, NA, 3L, 11L)\n  expect_identical(y[sel], setNames(as.integer64(x[sel]), names(x)[sel]))\n\n  sel = c(1.0, NA, 3.0, 11.0)\n  expect_identical(y[sel], setNames(as.integer64(x[sel]), names(x)[sel]))\n  expect_identical(y[as.integer64(sel)], setNames(as.integer64(x[sel]), names(x)[sel]))\n\n  sel = c(-1L, -3L, 0L, -11L)\n  expect_identical(y[sel], setNames(as.integer64(x[sel]), names(x)[sel]))\n\n  sel = c(-1.0, -3.0, 0.0, -11.0)\n  expect_identical(y[sel], setNames(as.integer64(x[sel]), names(x)[sel]))\n\n  # `only 0's may be mixed with negative subscripts`\n  sel = c(-1.0, -3.0, 0.0, -11.0, NA)\n  expect_same_error(x[sel], y[sel])\n\n  expect_identical(\n    as.integer64(c(\"9218868437227407266\", \"1\"))[c(1L, NA, 3L, 4L)],\n    as.integer64(c(\"9218868437227407266\", NA, NA, NA))\n  )\n\n  sel = c(\"d\", \"\", \"b\", NA_character_)\n  expect_identical(y[sel], setNames(as.integer64(x[sel]), names(x[sel])))\n\n  expect_identical(lapply(list(integer64()), `[`, 0L), list(integer64()))\n\n  getter = function(x, ...) x[...]\n\n  i64 = integer64(1L)\n  names(i64) = \"a\"\n  expect_identical(getter(i64), i64)\n  expect_identical(getter(i64, 1L), i64)\n  expect_identical(getter(i64, \"a\"), i64)\n\n  i32 = integer(1L)\n  names(i32) = \"a\"\n  expect_identical(getter(i32), i32)\n  expect_identical(getter(i32, 1L), i32)\n  expect_identical(getter(i32, \"a\"), i32)\n\n  l = list(integer(1L), integer(2L), integer(3L))\n  expect_identical(\n    lapply(l, getter, 1L),\n    list(integer(1L), integer(1L), integer(1L))\n  )\n})"

