const rtdal000213Source0044 = "test_that(\"extraction works consistent to integer: matrix[\", {\n  m32 = matrix(1:10, nrow=2L)\n  m64 = matrix64(as.integer64(m32), nrow=dim(m32)[1L], ncol=dim(m32)[2L])\n\n  expect_identical(m32[integer(), 1:2, drop=TRUE], array(integer(), dim=c(0L, 2L)))\n  expect_identical(m64[integer(), 1:2, drop=TRUE], array(integer64(), dim=c(0L, 2L)))\n\n  expect_identical(m32[1:2, integer(), drop=TRUE], array(integer(), dim=c(2L, 0L)))\n  expect_identical(m64[1:2, integer(), drop=TRUE], array(integer64(), dim=c(2L, 0L)))\n\n  expect_identical(m32[integer(), 1:2, drop=FALSE], array(integer(), dim=c(0L, 2L)))\n  expect_identical(m64[integer(), 1:2, drop=FALSE], array(integer64(), dim=c(0L, 2L)))\n\n  expect_identical(m32[1:2, integer(), drop=FALSE], array(integer(), dim=c(2L, 0L)))\n  expect_identical(m64[1:2, integer(), drop=FALSE], array(integer64(), dim=c(2L, 0L)))\n\n  expect_identical(m32[1:2, 1:3, drop=TRUE], array(1:6, dim=c(2L, 3L)))\n  expect_identical(m64[1:2, 1:3, drop=TRUE], array(as.integer64(1:6), dim=c(2L, 3L)))\n\n  expect_identical(m32[1:2], 1:2)\n  expect_identical(m64[1:2], as.integer64(1:2))\n\n  expect_identical(m32[1:2, drop=TRUE], 1:2)\n  expect_identical(m64[1:2, drop=TRUE], as.integer64(1:2))\n\n  expect_identical(m32[j = 1:3, drop=TRUE], 1:3)\n  expect_identical(m64[j = 1:3, drop=TRUE], as.integer64(1:3))\n\n  expect_identical(m32[1:2, , drop=TRUE], array(as.integer(1:10), dim=c(2L, 5L)))\n  expect_identical(m64[1:2, , drop=TRUE], array(as.integer64(1:10), dim=c(2L, 5L)))\n\n  expect_identical(m32[, 1:3, drop=TRUE], array(as.integer(1:6), dim=c(2L, 3L)))\n  expect_identical(m64[, 1:3, drop=TRUE], array(as.integer64(1:6), dim=c(2L, 3L)))\n\n  expect_identical(m32[1L, , drop=TRUE], c(1L, 3L, 5L, 7L, 9L))\n  expect_identical(m64[1L, , drop=TRUE], as.integer64(c(1L, 3L, 5L, 7L, 9L)))\n\n  expect_identical(m32[1L, , drop=FALSE], array(c(1L, 3L, 5L, 7L, 9L), dim=c(1L, 5L)))\n  expect_identical(m64[1L, , drop=FALSE], array(as.integer64(c(1L, 3L, 5L, 7L, 9L)), dim=c(1L, 5L)))\n\n  expect_identical(m32[, 1L, drop=TRUE], 1:2)\n  expect_identical(m64[, 1L, drop=TRUE], as.integer64(1:2))\n\n  expect_identical(m32[, 1L, drop=FALSE], array(1:2, dim=2:1))\n  expect_identical(m64[, 1L, drop=FALSE], array(as.integer64(1:2), dim=2:1))\n\n  expect_identical(m32[c(9L, NA, 11L, 12L), drop=FALSE], c(9L, NA, NA, NA))\n  expect_identical(m64[c(9L, NA, 11L, 12L), drop=FALSE], as.integer64(c(9L, NA, NA, NA)))\n\n  expect_identical(m32[integer(), c(1:2, 0L, NA), drop=TRUE], array(integer(), dim=c(0L, 3L)))\n  expect_identical(m64[integer(), c(1:2, 0L, NA), drop=TRUE], array(integer64(), dim=c(0L, 3L)))\n  expect_identical(m64[integer64(), c(1:2, 0L, NA), drop=TRUE], array(integer64(), dim=c(0L, 3L)))\n\n  expect_identical(m32[, c(1:2, 0L, NA), drop=TRUE], array(c(1:4, NA, NA), dim=c(2L, 3L)))\n  expect_identical(m64[, c(1:2, 0L, NA), drop=TRUE], array(as.integer64(c(1:4, NA, NA)), dim=c(2L, 3L)))\n\n  expect_identical(\n    m32[c(1L, NA, 2L), 1:3, drop=TRUE],\n    array(c(1L, NA, 2L, 3L, NA, 4L, 5L, NA, 6L), dim=c(3L, 3L))\n  )\n  expect_identical(\n    m64[c(1L, NA, 2L), 1:3, drop=TRUE],\n    array(as.integer64(c(1L, NA, 2L, 3L, NA, 4L, 5L, NA, 6L)), dim=c(3L, 3L))\n  )\n\n  m32 = matrix(1:10, 2L, dimnames = list(LETTERS[1:2], letters[1:5]))\n  m64 = matrix64(as.integer64(1:10), nrow=2L, ncol=5L, dimnames = list(LETTERS[1:2], letters[1:5]))\n\n  # `subscript out of bounds`\n  expect_same_error(\n    m32[c(\"B\", \"D\", \"A\"), c(\"d\", \"a\")],\n    m64[c(\"B\", \"D\", \"A\"), c(\"d\", \"a\")]\n  )\n\n  expect_identical(m32[c(\"B\", \"D\", \"A\")], rep(NA_integer_, 3L))\n  expect_identical(m64[c(\"B\", \"D\", \"A\")], rep(NA_integer64_, 3L))\n})"

const rtdal000213Source0045 = "test_that(\"replacement works consistent to integer: matrix[<-\", {\n  m32 = matrix(1:10, nrow=2L)\n  m64 = matrix64(as.integer64(m32), nrow=dim(m32)[1L], ncol=dim(m32)[2L])\n\n  local({\n    m32[1L, c(1L, 3L, NA)] = 100L\n    m64[1L, c(1L, 3L, NA)] = as.integer64(100L)\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n  local({\n    m32[1L, c(1L, 4L, NA)] = 101L\n    m64[1L, c(1L, 4L, NA)] = 101L\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n  local({\n    m32[1L, c(1L, 5L, NA)] = 102.0\n    m64[1L, c(1L, 5L, NA)] = 102.0\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n  local({\n    m32[1L, c(1L, 5L, NA)] = 102.0 + 0.0i\n    m64[1L, c(1L, 5L, NA)] = 102.0 + 0.0i\n    expect_identical(m64, m32)\n  })\n  # TODO(#44): remove this deprecated test\n  local({\n    m32[1L, c(1L, 3L, NA)] = 103L\n    m64[1L, c(1L, 3L, NA)] = \"103\"\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n  local({\n    # TODO(#44): remove `withr::local_options`\n    withr::local_options(list(bit64.promoteInteger64ToCharacter=TRUE))\n    m32[1L, c(1L, 3L, NA)] = \"103\"\n    m64[1L, c(1L, 3L, NA)] = \"103\"\n    expect_identical(m64, m32)\n  })\n  local({\n    m32[1L, c(1L, 3L, NA)] = 101L\n    m64[1L, as.integer64(c(1L, 3L, NA))] = 101L\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n  local({\n    m32[, -(1:3)] = 102L\n    m64[, -(1:3)] = 102L\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n})"

const rtdal000213Source0046 = "test_that(\"extraction works consistent to integer: matrix[[\", {\n  m32 = matrix(1:10, 2L, dimnames = list(LETTERS[1:2], letters[1:5]))\n  m64 = matrix64(as.integer64(1:10), nrow=2L, ncol=5L, dimnames=list(LETTERS[1:2], letters[1:5]))\n\n  expect_identical(m64[[1L, 2L]], as.integer64(m32[[1L, 2L]]))\n  expect_identical(m64[[as.integer64(1L), as.integer64(2L)]], as.integer64(m32[[1L, 2L]]))\n  expect_identical(m64[[\"A\", \"d\"]], as.integer64(m32[[\"A\", \"d\"]]))\n\n  expect_identical(m64[[1L]], as.integer64(m32[[1L]]))\n  expect_identical(m64[[as.integer64(1L)]], as.integer64(m32[[1L]]))\n\n  # `subscript out of bounds`\n  expect_same_error(m32[[NA]], m64[[NA]])\n  expect_same_error(m32[[NA]], m64[[NA_integer64_]])\n\n  # `attempt to select less than one element in integerOneIndex`\n  expect_same_error(m32[[0L]], m64[[0L]])\n  expect_same_error(m32[[0L]], m64[[as.integer64(0L)]])\n\n  # `attempt to select less than one element in get1index`\n  expect_same_error(m32[[integer()]], m64[[integer()]])\n  expect_same_error(m32[[integer()]], m64[[integer64()]])\n})"

const rtdal000213Source0047 = "test_that(\"replacement works consistent to integer: matrix[[<-\", {\n  m32 = matrix(1:10, 2L, dimnames = list(LETTERS[1:2], letters[1:5]))\n  m64 = matrix64(as.integer64(1:10), nrow=2L, ncol=5L, dimnames=list(LETTERS[1:2], letters[1:5]))\n\n  local({\n    m32[[1L, 3L]] = 110L\n    m64[[1L, 3L]] = 110L\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n  local({\n    m32[[\"A\", \"e\"]] = 112L\n    m64[[\"A\", \"e\"]] = 112L\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n  local({\n    m32[[1L, 3L]] = 111.0\n    m64[[1L, 3L]] = 111.0\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n    local({\n    m32[[1L, 3L]] = 111.0 + 0.0i\n    m64[[1L, 3L]] = 111.0 + 0.0i\n    expect_identical(m64, m32)\n  })\n  # TODO(#44): remove this deprecated test\n  local({\n    m32[[1L, 4L]] = 112L\n    m64[[1L, 4L]] = \"112\"\n    expect_identical(m64, array(as.integer64(m32), dim=dim(m32), dimnames=dimnames(m32)))\n  })\n  local({\n    # TODO(#44): remove `withr::local_options`\n    withr::local_options(list(bit64.promoteInteger64ToCharacter=TRUE))\n    m32[[1L, 4L]] = \"112\"\n    m64[[1L, 4L]] = \"112\"\n    expect_identical(m64, m32)\n  })\n\n})"

const rtdal000213Source0048 = `test_that("extraction consistent to integer: array[", {
  a32 = array(1:27, c(3L, 3L, 3L))
  a64 = array64(as.integer64(1:27), c(3L, 3L, 3L))

  expect_identical(a32[2L, , 3L, drop=FALSE], array(c(20L, 23L, 26L), dim = c(1L, 3L, 1L)))
  expect_identical(a64[2L, , 3L, drop=FALSE], array(as.integer64(c(20L, 23L, 26L)), dim = c(1L, 3L, 1L)))

  expect_identical(a32[2L, , 3L, drop=TRUE], c(20L, 23L, 26L))
  expect_identical(a64[2L, , 3L, drop=TRUE], as.integer64(c(20L, 23L, 26L)))

  expect_identical(
    a32[1L, c(1L, 3L, 2L), 2:3, drop=TRUE],
    array(c(10L, 16L, 13L, 19L, 25L, 22L), dim = 3:2)
  )
  expect_identical(
    a64[1L, c(1L, 3L, 2L), 2:3, drop=TRUE],
    array(as.integer64(c(10L, 16L, 13L, 19L, 25L, 22L)), dim = 3:2)
  )

  expect_identical(
    a32[, c(1L, 2L, 0L, 3L, NA, 1L), c(TRUE, FALSE, NA), drop=FALSE],
    array(
      c(1:9, rep(NA, 3L), 1:3, rep(NA, 15L)),
      dim = c(3L, 5L, 2L)
    )
  )
  expect_identical(
    a64[, c(1L, 2L, 0L, 3L, NA, 1L), c(TRUE, FALSE, NA), drop=FALSE],
    array(
      as.integer64(c(1:9, rep(NA, 3L), 1:3, rep(NA, 15L))),
      dim = c(3L, 5L, 2L)
    )
  )

  expect_identical(
    a32[, c(1L, 2L, 0L, 3L, NA, 1L), c(TRUE, FALSE, NA), drop=TRUE],
    array(
      c(1:9, rep(NA, 3L), 1:3, rep(NA, 15L)),
      dim = c(3L, 5L, 2L)
    )
  )
  expect_identical(
    a64[, c(1L, 2L, 0L, 3L, NA, 1L), c(TRUE, FALSE, NA), drop=TRUE],
    array(
      as.integer64(c(1:9, rep(NA, 3L), 1:3, rep(NA, 15L))),
      dim = c(3L, 5L, 2L)
    )
  )

  expect_identical(a32[c(1L, 0L, 7L, NA, 27L, 28L), drop=FALSE], c(1L, 7L, NA, 27L, NA))
  expect_identical(a64[c(1L, 0L, 7L, NA, 27L, 28L), drop=FALSE], as.integer64(c(1L, 7L, NA, 27L, NA)))

  expected =
    c(1L, NA, 4L, 5L, NA, 8L, 9L, NA, 12L, 13L, NA, 16L, 17L, NA, 20L, 21L, NA, 24L, 25L, NA)
  expect_identical(a32[c(TRUE, FALSE, NA, TRUE), drop=FALSE], expected)
  expect_identical(a64[c(TRUE, FALSE, NA, TRUE), drop=FALSE], as.integer64(expected))

  expect_identical(
    a32[-1L, , -c(0L, 2:3), drop=FALSE],
    array(c(2L, 3L, 5L, 6L, 8L, 9L), dim = c(2L, 3L, 1L))
  )
  expect_identical(
    a64[-1L, , -c(0L, 2:3), drop=FALSE],
    array(as.integer64(c(2L, 3L, 5L, 6L, 8L, 9L)), dim = c(2L, 3L, 1L))
  )

  expect_identical(a32[-1L, 2L, -c(0L, 2:3), drop=FALSE], array(5:6, dim = c(2L, 1L, 1L)))
  expect_identical(a64[-1L, 2L, -c(0L, 2:3), drop=FALSE], array(as.integer64(5:6), dim = c(2L, 1L, 1L)))

  expect_identical(a32[-1L, 2L, -c(0L, 2:3), drop=TRUE], 5:6)
  expect_identical(a64[-1L, 2L, -c(0L, 2:3), drop=TRUE], as.integer64(5:6))
})`

const rtdal000213Source0049 = `test_that("extraction from subclass retains inheritance structure", {
  x = as.integer64(1:2)
  class(x) = c("subclass", "integer64")

  expect_identical(x[1:2], x)

  y = x
  y[2L] = as.integer64(3L)
  # nolint next: undesirable_function_linter.
  expect_identical(y, structure(unclass(as.integer64(c(1L, 3L))), class=class(x)))

  x1 = x[[1L]]
  # nolint next: undesirable_function_linter.
  expect_identical(x1, structure(unclass(x)[1L], class=class(x)))

  y[[2L]] = as.integer64(4L)
  # nolint next: undesirable_function_linter.
  expect_identical(y, structure(unclass(as.integer64(c(1L, 4L))), class=class(x)))
})`

const rtdal000213Source0050 = `test_that("c works consistent to R", {
  convert_x32_result_to_integer64 = function(x, x32=x, recursive=FALSE) {
    if (isTRUE(recursive))
      ret = as.integer64(x)
    else
      ret = lapply(seq_along(x), function(el) if (el <= length(x32)) as.integer64(x[[el]]) else x[[el]])
    names(ret) = names(x)
    ret
  }

  x32 = 1:10
  x64 = as.integer64(x32)

  expect_identical(
    c(A=integer64(), B=as.raw(x32)),
    convert_x32_result_to_integer64(c(A=integer(), B=as.raw(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=integer64(), B=as.logical(x32)),
    convert_x32_result_to_integer64(c(A=integer(), B=as.logical(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=integer64(), B=as.difftime(x32, units="secs")),
    convert_x32_result_to_integer64(c(A=integer(), B=as.difftime(x32, units="secs")), recursive=TRUE)
  )
  expect_identical(
    c(A=integer64(), B=as.POSIXct(x32, origin="2026-01-27")),
    convert_x32_result_to_integer64(c(A=integer(), B=as.POSIXct(x32, origin="2026-01-27")), recursive=TRUE)
  )
  expect_identical(
    c(A=integer64(), B=as.Date(x32, origin="2026-01-27")),
    convert_x32_result_to_integer64(c(A=integer(), B=as.Date(x32, origin="2026-01-27")), recursive=TRUE)
  )
  expect_identical(
    c(A=integer64(), B=as.factor(x32)),
    convert_x32_result_to_integer64(c(A=integer(), B=as.factor(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=integer64(), B=as.ordered(x32)),
    convert_x32_result_to_integer64(c(A=integer(), B=as.ordered(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=integer64(), B=as.double(x32)),
    convert_x32_result_to_integer64(c(A=integer(), B=as.double(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=integer64(), B=x32),
    convert_x32_result_to_integer64(c(A=integer(), B=x32), recursive=TRUE)
  )
  expect_identical(c(A=integer64(), B=as.complex(x32)), c(A=integer(), B=as.complex(x32)))
  # TODO(#44): adjust tests accordingly
  expect_identical(
    c(A=integer64(), B=as.character(x32)),
    convert_x32_result_to_integer64(c(A=integer(), B=as.character(x32)), recursive=TRUE)
  )
  withr::with_options(list(bit64.promoteInteger64ToCharacter=TRUE), {
    expect_identical(c(A=integer64(), B=as.character(x32)), c(A=integer(), B=as.character(x32)))
  })

  expect_identical(
    c(A=x64, B=as.raw(x32)),
    convert_x32_result_to_integer64(c(A=x32, B=as.raw(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=as.logical(x32)),
    convert_x32_result_to_integer64(c(A=x32, B=as.logical(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=as.difftime(x32, units="secs")),
    convert_x32_result_to_integer64(c(A=x32, B=as.difftime(x32, units="secs")), recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=as.POSIXct(x32, origin="2026-01-27")),
    convert_x32_result_to_integer64(c(A=x32, B=as.POSIXct(x32, origin="2026-01-27")), recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=as.Date(x32, origin="2026-01-27")),
    convert_x32_result_to_integer64(c(A=x32, B=as.Date(x32, origin="2026-01-27")), recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=as.factor(x32)),
    convert_x32_result_to_integer64(c(A=x32, B=as.factor(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=as.ordered(x32)),
    convert_x32_result_to_integer64(c(A=x32, B=as.ordered(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=as.double(x32)),
    convert_x32_result_to_integer64(c(A=x32, B=as.double(x32)), recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=x32),
    convert_x32_result_to_integer64(c(A=x32, B=x32), recursive=TRUE)
  )
  expect_identical(c(A=x64, B=as.complex(x32)), c(A=x32, B=as.complex(x32)))
  # TODO(#44): adjust tests accordingly
  expect_identical(
    c(A=x64, B=as.character(x32)),
    convert_x32_result_to_integer64(c(A=x32, B=as.character(x32)), recursive=TRUE)
  )
  withr::with_options(list(bit64.promoteInteger64ToCharacter=TRUE), {
    expect_identical(c(A=x64, B=as.character(x32)), c(A=x32, B=as.character(x32)))
  })

  # regarding lists
  expect_identical(
    c(A=integer64(), B=list()),
    convert_x32_result_to_integer64(c(A=integer(), B=list()), integer())
  )
  expect_identical(
    c(A=integer64(), B=list(), recursive=TRUE),
    convert_x32_result_to_integer64(c(A=integer64(), B=list(), recursive=TRUE), integer(), recursive=TRUE)
  )
  expect_identical(
    c(A=integer64(), B=list(), C=1:2),
    convert_x32_result_to_integer64(c(A=integer(), B=list(), C=1:2), integer())
  )
  expect_identical(
    c(A=integer64(), B=list(), C=1:2, recursive=TRUE),
    convert_x32_result_to_integer64(c(A=integer(), B=list(), C=1:2, recursive=TRUE), integer(), recursive=TRUE)
  )

  expect_identical(
    c(A=x64, B=list()),
    convert_x32_result_to_integer64(c(A=x32, B=list()), x32)
  )
  expect_identical(
    c(A=x64, B=list(), recursive=TRUE),
    convert_x32_result_to_integer64(c(A=x32, B=list(), recursive=TRUE), x32, recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=list(), C=1:2),
    convert_x32_result_to_integer64(c(A=x32, B=list(), C=1:2), x32)
  )
  expect_identical(
    c(A=x64, B=list(), C=1:2, recursive=TRUE),
    convert_x32_result_to_integer64(c(A=x32, B=list(), C=1:2, recursive=TRUE), x32, recursive=TRUE)
  )
  expect_identical(
    c(A=x64, B=list(a=1:2, b=3L, c="4")),
    convert_x32_result_to_integer64(c(A=x32, B=list(a=1:2, b=3L, c="4")), x32)
  )
  # TODO(#44): adjust tests accordingly
  expect_identical(
    c(A=x64, B=list(a=1:2, b=3L, c="4"), recursive=TRUE),
    convert_x32_result_to_integer64(c(A=x32, B=list(a=1:2, b=3L, c="4"), recursive=TRUE), x32, recursive=TRUE)
  )
  withr::with_options(list(bit64.promoteInteger64ToCharacter=TRUE), {
    expect_identical(
      c(A=x64, B=list(a=1:2, b=3L, c="4"), recursive=TRUE),
      c(A=x32, B=list(a=1:2, b=3L, c="4"), recursive=TRUE)
    )
  })
  expect_identical(
    c(A=x64, B=data.frame(a=1:2, b=3L, c="4", stringsAsFactors=FALSE)),
    convert_x32_result_to_integer64(
      c(A=x32, B=data.frame(a=1:2, b=3L, c="4", stringsAsFactors=FALSE)),
      x32
    )
  )
  # TODO(#44): adjust tests accordingly
  expect_identical(
    c(A=x64, B=data.frame(a=1:2, b=3L, c="4", stringsAsFactors=FALSE), recursive=TRUE),
    convert_x32_result_to_integer64(
      c(A=x32, B=data.frame(a=1:2, b=3L, c="4", stringsAsFactors=FALSE), recursive=TRUE),
      x32,
      recursive = TRUE
    )
  )
  withr::with_options(list(bit64.promoteInteger64ToCharacter=TRUE), {
    expect_identical(
      c(A=x64, B=data.frame(a=1:2, b=3L, c="4", stringsAsFactors=FALSE), recursive=TRUE),
      c(A=x32, B=data.frame(a=1:2, b=3L, c="4", stringsAsFactors=FALSE), recursive=TRUE)
    )
  })

  expect_identical(
    c(x64, as.POSIXlt(x32, origin="2026-01-27")),
    convert_x32_result_to_integer64(c(x32, as.POSIXlt(x32, origin="2026-01-27")), x32)
  )
  if (getRversion() >= "4.0.0") # in my tests on R 3.5.0 this is identical
    expect_identical(
      c(x64, as.POSIXlt(x32, origin="2026-01-27"), recursive=TRUE),
      c(x32, as.POSIXlt(x32, origin="2026-01-27"), recursive=TRUE)
    )

  expect_identical(
    c(
      A = x64,
      B = list(aa=x64, bb=list(bba=x64, bbb=x32, bbc=as.character(x32))),
      C = data.frame(a=x64, b=x32)
    ),
    convert_x32_result_to_integer64(
      c(
        A = x32,
        B = list(aa=x64, bb=list(bba=x64, bbb=x32, bbc=as.character(x32))),
        C = data.frame(a=x64, b=x32)
      ),
      x32
    )
  )
  # TODO(#44): adjust tests accordingly
  expect_identical(
    c(
      A = x64,
      B = list(aa=x64, bb=list(bba=x64, bbb=x32, bbc=as.character(x32))),
      C = data.frame(a=x64, b=x32),
      recursive = TRUE
    ),
    convert_x32_result_to_integer64(
      c(
        A = x32,
        B = list(aa=x32, bb=list(bba=x32, bbb=x32, bbc=as.character(x32))),
        C = data.frame(a=x32, b=x32),
        recursive = TRUE
      ),
      recursive = TRUE
    )
  )
  withr::with_options(list(bit64.promoteInteger64ToCharacter=TRUE), {
    expect_identical(
      c(
        A = x64,
        B = list(aa=x64, bb=list(bba=x64, bbb=x32, bbc=as.character(x32))),
        C = data.frame(a=x64, b=x32),
        recursive = TRUE
      ),
      c(
        A = x32,
        B = list(aa=x32, bb=list(bba=x32, bbb=x32, bbc=as.character(x32))),
        C = data.frame(a=x32, b=x32),
        recursive = TRUE
      )
    )
  })
})`

