const rtdal000256Source0001 = `bs_add_variables <- function(
  theme,
  ...,
  .where = "defaults",
  .default_flag = identical(.where, "defaults")
) {
  assert_bs_theme(theme)

  vars <- rlang::list2(...)
  if (any(names2(vars) == "")) {
    stop("Variables must be named.", call. = FALSE)
  }

  # Workaround to the problem of 'blue' winning in the scenario of:
  # bs_add_variables("body-bg" = "blue")
  # bs_add_variables("body-bg" = "red")
  if (.default_flag) {
    vars <- ensure_default_flag(vars)
  }

  bs_bundle(
    theme,
    do.call(sass_layer, rlang::list2(!!.where := vars))
  )
}`

const rtdal000256Source0002 = "ensure_default_flag <- function(x) {\n  Map(\n    x,\n    rlang::names2(x),\n    f = function(val, nm) {\n      # sass::font_collection() has its own default_flag, so warn if they conflict\n      if (sass::is_font_collection(val)) {\n        if (identical(val$default_flag, FALSE)) {\n          message(\n            \"Ignoring `bs_add_variables()`'s `.default_flag = TRUE` for \",\n            \"the \",\n            nm,\n            \" variable (since it has its own `default_flag`).\"\n          )\n        }\n        return(val)\n      }\n      val <- paste(as_sass(val), collapse = \"\\n\")\n      if (grepl(\"!default\\\\s*;*\\\\s*$\", val)) {\n        val\n      } else {\n        paste(sub(\";+$\", \"\", val), \"!default\")\n      }\n    }\n  )\n}"

const rtdal000256Source0006 = `bs_bundle <- function(theme, ...) {
  assert_bs_theme(theme)
  structure(
    sass_bundle(theme, ...),
    class = class(theme)
  )
}`

